class Solution:
    def climbStairs(self, n: int) -> int:
        prev, cur = 1, 1  # ways to reach step 0 and step 1
        for _ in range(n - 1):
            prev, cur = cur, prev + cur  # the next step is reached from either of the last two
        return cur


