class Solution:
    def maxArea(self, height: List[int]) -> int:
        lo, hi = 0, len(height) - 1
        best = 0
        while lo < hi:
            best = max(best, min(height[lo], height[hi]) * (hi - lo))
            # The shorter wall cannot pair with anything inside to do better, so drop it
            if height[lo] < height[hi]:
                lo += 1
            else:
                hi -= 1
        return best

