class Solution:
    def decodeString(self, s: str) -> str:
        stack = []  # (text decoded before the bracket, repeat count) for each open bracket
        cur, num = "", 0
        for ch in s:
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch == "[":
                stack.append((cur, num))
                cur, num = "", 0
            elif ch == "]":
                prev, times = stack.pop()
                cur = prev + cur * times
            else:
                cur += ch
        return cur

