class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:  # the rotation point is right of mid
                lo = mid + 1
            else:  # nums[mid] < nums[hi]: the minimum is at mid or to its left
                hi = mid
        return nums[lo]

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        # Floyd's cycle detection on the functional graph i -> nums[i], from index 0
        slow = fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        # Restart one pointer from the beginning: they meet at the cycle's entrance
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        # Put each value v in 1..n at index v - 1; anything else is left where it is
        for i in range(n):
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                j = nums[i] - 1
                nums[i], nums[j] = nums[j], nums[i]
        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        return n + 1

