class Solution:
    def canJump(self, nums: List[int]) -> bool:
        reach = 0  # furthest index reachable so far
        for i, x in enumerate(nums):
            if i > reach:  # this index can't be reached, so nothing beyond it can be either
                return False
            reach = max(reach, i + x)
        return True

class Solution:
    def jump(self, nums: List[int]) -> int:
        jumps = end = farthest = 0  # end: last index reachable with `jumps` jumps
        for i in range(len(nums) - 1):
            farthest = max(farthest, i + nums[i])  # reach if one more jump is taken from here
            if i == end:  # the current layer is used up, so one more jump is needed
                jumps += 1
                end = farthest
        return jumps

