class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        seen = set(nums)  # O(1) membership; repeats collapse
        best = 0
        for x in seen:
            if x - 1 in seen:
                continue  # not the start of its run; the start walks the whole run
            length = 1
            while x + length in seen:
                length += 1
            best = max(best, length)
        return best

