class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # tails[k]: the smallest value that can end an increasing subsequence of length k + 1
        tails: List[int] = []
        for x in nums:
            k = bisect_left(tails, x)  # first tail >= x; x belongs at that spot
            if k == len(tails):
                tails.append(x)
            else:
                tails[k] = x
        return len(tails)


