class Solution:
    def numSquares(self, n: int) -> int:
        squares = []
        k = 1
        while k * k <= n:
            squares.append(k * k)
            k += 1
        best = list(range(n + 1))  # n copies of 1 is always a valid (if poor) answer
        for m in range(1, n + 1):
            for s in squares:
                if s > m:
                    break
                best[m] = min(best[m], best[m - s] + 1)  # last square is s
        return best[n]

