class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        n = len(nums)
        k %= n

        def reverse(lo: int, hi: int) -> None:
            while lo < hi:
                nums[lo], nums[hi] = nums[hi], nums[lo]
                lo, hi = lo + 1, hi - 1

        reverse(0, n - 1)  # the whole array: the last k elements are now first, reversed
        reverse(0, k - 1)  # put the first k back in order
        reverse(k, n - 1)  # and the rest

class Solution:
    def rotate(self, matrix: List[List[int]]) -> None:
        n = len(matrix)
        # Transpose: swap across the main diagonal
        for i in range(n):
            for j in range(i + 1, n):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
        # Reverse each row: together with the transpose this is a clockwise turn
        for row in matrix:
            row.reverse()

