    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        lo, hi = 0, m * n  # half-open range of flat indices
        while lo < hi:
            mid = (lo + hi) // 2
            if matrix[mid // n][mid % n] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo < m * n and matrix[lo // n][lo % n] == target


