class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # ways[j]: routes to column j of the current row; the first row has one route per cell
        ways = [1] * n
        for _ in range(1, m):
            for j in range(1, n):
                # ways[j] still holds the cell above; ways[j - 1] already holds the cell to the left
                ways[j] += ways[j - 1]
        return ways[-1]

