class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        words = set(wordDict)
        longest = max(map(len, words))
        ok = [True] + [False] * len(s)  # ok[i]: s[:i] can be split into words
        for i in range(1, len(s) + 1):
            ok[i] = any(ok[j] and s[j:i] in words for j in range(max(0, i - longest), i))
        return ok[-1]

class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows, cols = len(board), len(board[0])
        visited = set()

        def dfs(r: int, c: int, k: int) -> bool:
            # Can word[k:] be read starting at (r, c), without reusing visited cells?
            if board[r][c] != word[k]:
                return False
            if k == len(word) - 1:
                return True
            visited.add((r, c))
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                    if dfs(nr, nc, k + 1):
                        return True
            visited.discard((r, c))  # undo the mark: this cell may be needed by another branch
            return False

        return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

